// inline-SVG-with-currentColor convention. To regenerate / add an icon, see
// scripts/gen-geist-icons.md. Colors are `currentColor` only (no literals) so
// the design-system color lint passes; size via the `size` prop (default 16).
import type { SVGProps } from 'react'

export interface IconProps extends Omit<SVGProps<SVGSVGElement>, 'fill'> {
  /** Square pixel size (width = height). Defaults to 16. */
  size?: number
}

function GeistIcon({ size = 16, children, ...props }: IconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
      {...props}
    >
      {children}
    </svg>
  )
}

